def _build_doc(self):
    """
        Raises
        ------
        ValueError
            * If a URL that lxml cannot parse is passed.

        Exception
            * Any other ``Exception`` thrown. For example, trying to parse a
              URL that is syntactically correct on a machine with no internet
              connection will fail.

        See Also
        --------
        pandas.io.html._HtmlFrameParser._build_doc
        """
    from lxml.etree import XMLSyntaxError
    from lxml.html import HTMLParser, fromstring, parse
    parser = HTMLParser(recover=True, encoding=self.encoding)
    try:
        if is_url(self.io):
            with urlopen(self.io) as f:
                r = parse(f, parser=parser)
        else:
            r = parse(self.io, parser=parser)
        try:
            r = r.getroot()
        except AttributeError:
            pass
    except (UnicodeDecodeError, OSError) as e:
        if not is_url(self.io):
            r = fromstring(self.io, parser=parser)
            try:
                r = r.getroot()
            except AttributeError:
                pass
        else:
            raise e
    else:
        if not hasattr(r, 'text_content'):
            raise XMLSyntaxError('no text parsed from document', 0, 0, 0)
    return r

def _parse(flavor, io, match, attrs, encoding, displayed_only, **kwargs):
    flavor = _validate_flavor(flavor)
    compiled_match = re.compile(match)
    retained = None
    for flav in flavor:
        parser = _parser_dispatch(flav)
        p = parser(io, compiled_match, attrs, encoding, displayed_only)
        try:
            tables = p.parse_tables()
        except ValueError as caught:
            if hasattr(io, 'seekable') and io.seekable():
                io.seek(0)
            elif hasattr(io, 'seekable') and not io.seekable():
                raise ValueError(
                    f"The flavor {flav} failed to parse your input. Since you passed a non-rewindable file object, we can't rewind it to try another parser. Try read_html() with a different flavor."
                    ) from caught
            retained = caught
        else:
            break
    else:
        assert retained is not None
        raise retained
    ret = []
    for table in tables:
        try:
            ret.append(_data_to_frame(data=table, **kwargs))
        except EmptyDataError:
            continue
    return ret

